/* C Lab answers page – builds on ../style.css */

.small { font-size: 14px; margin-top: 16px; }

.lab-notes {
  margin: 20px 0 0 20px;
  color: var(--muted);
  line-height: 1.7;
  font-size: 15px;
}

.btn--sm { padding: 7px 14px; font-size: 13px; }

/* ── Table of contents ── */
.toc-wrap { padding-top: 0; }
.toc-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
.toc-head .subhead { flex: 1; margin-top: 0; }
.toc {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 8px;
}
.toc a {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 2px;
  text-decoration: none;
  font-size: 14px;
  transition: border-color .15s, color .15s;
}
.toc a:hover { border-color: var(--rust); color: var(--rust); }
.toc a span {
  flex: none;
  width: 28px;
  font-family: "JetBrains Mono", monospace;
  font-weight: 700;
  color: var(--rust);
}

/* ── Experiments ── */
.experiment {
  max-width: 1100px;
  margin: 0 auto;
  padding: 64px 20px 0;
  scroll-margin-top: 60px;
}
.experiment h2 { font-size: clamp(22px, 3vw, 28px); margin-bottom: 6px; }
.experiment .lead { color: var(--muted); margin-bottom: 18px; }

/* ── One program ── */
.program {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 2px;
  margin-bottom: 10px;
  scroll-margin-top: 70px;
}
.program[open] { border-color: rgba(184, 67, 10, .45); }
.program summary {
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding: 14px 18px;
  font-weight: 600;
}
.program summary::-webkit-details-marker { display: none; }
.program summary::after {
  content: "+";
  margin-left: auto;
  font-family: "JetBrains Mono", monospace;
  color: var(--rust);
}
.program[open] summary::after { content: "−"; }
.program summary:hover { color: var(--rust); }
.pnum { font-family: "JetBrains Mono", monospace; font-size: 13px; color: var(--rust); min-width: 36px; }

.pbody { padding: 0 18px 18px; }
.pnote { color: var(--muted); line-height: 1.6; margin-bottom: 14px; font-size: 15px; font-variant-ligatures: none; }

.code-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 14px;
  background: #2e2925;
  border-radius: 4px 4px 0 0;
}
.fname { font-family: "JetBrains Mono", monospace; font-size: 13px; color: #d9cfc3; }
.code-actions { display: flex; gap: 8px; }
.code-actions button,
.code-actions a {
  font-family: "Inter Tight", sans-serif;
  font-size: 12.5px;
  font-weight: 600;
  padding: 4px 10px;
  border: 1px solid #5a514a;
  border-radius: 2px;
  background: transparent;
  color: #e9e1d6;
  text-decoration: none;
  cursor: pointer;
}
.code-actions button:hover,
.code-actions a:hover { border-color: #f0b48c; color: #f0b48c; }

pre.code {
  margin: 0;
  padding: 16px 18px;
  background: #1f1b18;
  color: #e9e1d6;
  border-radius: 0 0 4px 4px;
  overflow-x: auto;
  font-size: 14px;
  line-height: 1.6;
}
pre, pre code { font-family: "JetBrains Mono", monospace; font-variant-ligatures: none; }

/* Syntax colours (highlight.js classes) */
.hljs-keyword, .hljs-type, .hljs-built_in { color: #f0b48c; }
.hljs-string { color: #9fd3a8; }
.hljs-number, .hljs-literal { color: #e6c07b; }
.hljs-comment { color: #9a8f84; font-style: italic; }
.hljs-meta, .hljs-meta .hljs-keyword { color: #c9a0dc; }
.hljs-meta .hljs-string { color: #9fd3a8; }
.hljs-title, .hljs-title.function_ { color: #8cc4e8; }

/* Input / output */
.io {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 10px;
  margin-top: 12px;
}
.io-box { border: 1px solid var(--line); border-radius: 2px; background: var(--cream); }
.io-box h4 {
  font-family: "JetBrains Mono", monospace;
  font-size: 11px;
  font-weight: 500;
  color: var(--muted);
  letter-spacing: .04em;
  padding: 8px 12px 0;
}
.io-box pre {
  padding: 6px 12px 12px;
  font-size: 13.5px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}
.io-out { grid-column: 1 / -1; }
.io-out pre { color: var(--ink); }

@media (max-width: 768px) {
  .experiment { padding: 48px 16px 0; }
  .program summary { padding: 12px 14px; gap: 10px; }
  .pbody { padding: 0 12px 14px; }
  pre.code { font-size: 12.5px; padding: 12px; }
}
